vec4 qq;
float sc;

vec4 qm( vec4 v, vec4 w ) { 
// to multiply 2 quaternions by FabriceNeyret2
     vec2 s=vec2(1,-1);
     return w * mat4( v*s.xyyy, v.yxwz*s.xxxy, v.zwxy*s.xyxx, v.wzyx*s.xxyx );
}

float df(vec4 q) {  
    vec4 q2 = vec4(1,0,0,0); 
    sc= 1.;     
    for (int i; i++<4; q2 = q )    
        q = cos( qm(q,q)/1.2 ) + vec4(-1,0,0,0),
        sc *= length(q)/length(q2);         

    float d = clamp(dot(q,q),1e-3,1e4); 

    qq = q*q/sc;
    return  sqrt(sqrt(sqrt(d/sc))) * log(d);
}

#define rot(a)  mat2(cos(a+vec4(0,11,33,0)))

void mainImage( out vec4 O, vec2 U) {

    float t=iTime+33.5;
    O *= 0.;
    vec2 R = iResolution.xy;
    vec4 D = normalize( vec4( U+U-R, R.y, R.y) )*2. ,
         p = vec4(12,1,1,-3);  

    p.xz *= rot(1.);
    p.xy *= rot(.6);
    p.yw *= rot( .02*sin(t/5.));
    p.xw *= rot( .01*cos(t/16.));

    float totdist;
    for (float d,i ; ++i<10.; ) 
        d = df(p)/20.,
        p += d * D,
        totdist += d,
        d > .02  ?  
            O += 
            //.1*( log(qq) )
            .6*cos( log(qq) + vec4(1,2,3,0) )  //just changed it to this
            / exp(i*i*i*d*d*10.) 
            : O ;


    O *= exp(-totdist*totdist*2.);
    O = 1. - exp(-O*O);  
}
